for (const c of C) { c.split = split(c.t); c.rr = c.geo.rr; c.f = { vol: !!c.vol_ok, ov: !!c.overext_ok, rr: c.geo.rr >= 1.7, q: c.q_final >= c.q_th, fresh: !c.fresh_opp, two: !c.two_factor, htf: !c.htf_conflict }; c.f.all = Object.values(c.f).every(Boolean); c.isSig = c.act === 'BUY' || c.act === 'SELL'; c.row = ROWS.get(c.i) ?? null; c.src = 'CAND'; }
