function ntGates(r, side) { if (!(r.atr >= 2.0)) return 'ATR_FLOOR'; if (Math.abs(r.e20d) > 2.5) return 'OVEREXTENDED'; if ((r.b15d === 'BULLISH' && side === 'SELL') || (r.b15d === 'BEARISH' && side === 'BUY')) return 'BIAS_OPPOSED'; const trendOpp = (side === 'BUY' && r.m30r === 'BEAR_TREND' && r.m30s === 'BEARISH') || (side === 'SELL' && r.m30r === 'BULL_TREND' && r.m30s === 'BULLISH'); if (trendOpp) return 'TWO_FACTOR_30M'; return null; }
